  const item: SecretaryReport = { id: recordId, masterId: publisher.masterId, competencia, categoria: publisher.categoria, participou: String(data.get('participou')) === 'true', estudos: number('estudos'), horasCampo: number('horasCampo'), horasAtividadeAprovada: number('horasAtividadeAprovada'), creditoHoras: number('creditoHoras'), pioneiroAuxiliar: String(data.get('pioneiroAuxiliar')) === 'true', observacoes: String(data.get('observacoes') ?? '').trim().slice(0, 250), atrasado: isReportLate(competencia, recebidoEm) || String(data.get('atrasado')) === 'true', recebidoEm, atualizadoEm: new Date().toISOString(), origem: currentReportOrigin() }
